#!/usr/bin/env python3
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]

p=ROOT/'runtime/sword_runtime/fortified_site_runtime.py'
s=p.read_text()
# Replace the retired handheld-crossbow crew-control helper with ordinary garrison emplacement-service logic.
pat=re.compile(r'''    def _siege_crossbow_crew_control\(self, refs: list\[str\]\) -> float:\n.*?\n    def _siege_bed_crossbow_physics''',re.S)
m=pat.search(s)
if not m:
 raise SystemExit('bed-crossbow crew helper block not found')
new='''    @staticmethod\n    def _siege_emplacement_row_score(row: Mapping[str, Any]) -> float:\n        """Service quality for a fixed mechanical emplacement, never handheld Crossbow skill.\n\n        Bed-crossbow launch energy belongs to the latched mechanism. Existing\n        garrison soldiers can crew it; engineering familiarity, formation drill,\n        coordination, awareness and composure improve pointing/ranging/reload only.\n        """\n        skills = row.get("skills", {}) if isinstance(row.get("skills"), Mapping) else {}\n        attrs = row.get("attributes", {}) if isinstance(row.get("attributes"), Mapping) else {}\n        engineering = float(skills.get("Engineering", 0) or 0)\n        formation = float(skills.get("Formation Fighting", skills.get("Formation_Fighting", row.get("formation_fighting", 0))) or 0)\n        coordination = float(attrs.get("Coordination", row.get("ranged_coordination", 0)) or 0)\n        awareness = float(attrs.get("Awareness", row.get("ranged_awareness", 0)) or 0)\n        composure = float(attrs.get("Composure", 0) or 0)\n        intelligence = float(attrs.get("Intelligence", 0) or 0)\n        training = float(row.get("formation_training", 20) or 20)\n        cohesion = float(row.get("formation_cohesion", 50) or 50)\n        return max(0.0,\n            0.24 * engineering + 0.18 * formation + 0.15 * coordination +\n            0.14 * awareness + 0.10 * composure + 0.07 * intelligence +\n            0.06 * training + 0.06 * cohesion\n        )\n\n    def _siege_emplacement_crew_rows(self, refs: list[str]) -> list[dict[str, float | int]]:\n        """Return all lawful existing garrison bodies ranked for fixed-emplacement service."""\n        rows_out: list[dict[str, float | int]] = []\n        if not hasattr(self, "_combat_prepare_formation") or not hasattr(self, "_combat_cohort_snapshot"):\n            summary = self._garrison_summary(refs)\n            n = max(0, int(summary.get("personnel", 0) or 0))\n            if n:\n                rows_out.append({"count": n, "score": 75.0})\n            return rows_out\n        for ref in refs:\n            try:\n                _p, formation, force = self._combat_prepare_formation(str(ref))\n                rows = self._combat_cohort_snapshot(formation, force)\n            except (ValueError, KeyError, FileNotFoundError):\n                continue\n            for row in rows:\n                count = max(0, int(row.get("count", 0) or 0))\n                if count <= 0:\n                    continue\n                rows_out.append({"count": count, "score": self._siege_emplacement_row_score(row)})\n        return rows_out\n\n    @staticmethod\n    def _siege_allocate_crew(rows: list[dict[str, float | int]], requested_crew: int) -> tuple[int, float]:\n        need = max(0, int(requested_crew))\n        if need <= 0:\n            return 0, 0.0\n        used = 0\n        weighted = 0.0\n        for row in sorted(rows, key=lambda x: float(x.get("score", 0) or 0), reverse=True):\n            take = min(need - used, max(0, int(row.get("count", 0) or 0)))\n            if take <= 0:\n                continue\n            used += take\n            weighted += take * float(row.get("score", 0) or 0)\n            if used >= need:\n                break\n        return used, (weighted / used if used else 0.0)\n\n    def _siege_bed_crossbow_crew_control(self, refs: list[str], *, requested_crew: int | None = None) -> float:\n        """Return fixed-emplacement service control without using Crossbow skill."""\n        rows = self._siege_emplacement_crew_rows(refs)\n        if requested_crew is None:\n            requested_crew = sum(max(0, int(r.get("count", 0) or 0)) for r in rows)\n        _used, score = self._siege_allocate_crew(rows, requested_crew)\n        return score\n\n    def _siege_crossbow_crew_control(self, refs: list[str]) -> float:\n        """Compatibility alias: fixed fortress crossbows use emplacement service, not Crossbow proficiency."""\n        return self._siege_bed_crossbow_crew_control(refs)\n\n    def _siege_bed_crossbow_physics'''
s=s[:m.start()]+new+s[m.end():]
# Patch fortress artillery crew allocation.
old='''        crossbow = max(0, int(summary.get("crossbow_personnel", 0)))\n        engineers = max(0, int(summary.get("engineer_personnel", 0)))\n        personnel = max(0, int(summary.get("personnel", 0)))\n        bed_inst = max(0, int(installed.get("bed_crossbows", 0) or 0))\n        treb_inst = max(0, int(installed.get("counterweight_trebuchets", installed.get("trebuchets", 0)) or 0))\n        drop_inst = max(0, int(installed.get("stone_drop_cranes", installed.get("stone_drop_systems", 0)) or 0))\n        fire_inst = max(0, int(installed.get("firepot_systems", 0) or 0))\n\n        siege_rules = self.read("game/data/mechanics/siege.json")\n        bed_cfg = siege_rules.get("bed_crossbow", {}) if isinstance(siege_rules, Mapping) else {}\n        bed_min_crew = max(1, int(bed_cfg.get("minimum_crew", 4) or 4))\n        bed_serviceable = int(math.floor(bed_inst * condition))\n        bed = min(bed_serviceable, crossbow // bed_min_crew)\n        bed_fit_crew = min(crossbow, bed * max(bed_min_crew, int(bed_cfg.get("optimal_crew", 6) or 6)))\n        crossbow_left = max(0, crossbow - bed_fit_crew)\n        treb = min(int(math.floor(treb_inst * condition)), engineers // 60)\n        engineer_left = max(0, engineers - treb * 60)\n        drop = min(int(math.floor(drop_inst * condition)), engineer_left // 4)\n        engineer_left = max(0, engineer_left - drop * 4)\n        fire = min(int(math.floor(fire_inst * condition)), max(0, personnel - bed_fit_crew - treb * 60 - drop * 4) // 3)\n'''
new2='''        engineers = max(0, int(summary.get("engineer_personnel", 0)))\n        personnel = max(0, int(summary.get("personnel", 0)))\n        bed_inst = max(0, int(installed.get("bed_crossbows", 0) or 0))\n        treb_inst = max(0, int(installed.get("counterweight_trebuchets", installed.get("trebuchets", 0)) or 0))\n        drop_inst = max(0, int(installed.get("stone_drop_cranes", installed.get("stone_drop_systems", 0)) or 0))\n        fire_inst = max(0, int(installed.get("firepot_systems", 0) or 0))\n\n        siege_rules = self.read("game/data/mechanics/siege.json")\n        bed_cfg = siege_rules.get("bed_crossbow", {}) if isinstance(siege_rules, Mapping) else {}\n        bed_min_crew = max(1, int(bed_cfg.get("minimum_crew", 4) or 4))\n        bed_optimal_crew = max(bed_min_crew, int(bed_cfg.get("optimal_crew", 6) or 6))\n        bed_serviceable = int(math.floor(bed_inst * condition))\n        # Fixed emplacements draw crew from the ordinary garrison, not from a\n        # fictitious handheld-crossbow troop species. Best suited bodies are\n        # allocated first, but any fit garrison body may fill the minimum crew.\n        bed = min(bed_serviceable, personnel // bed_min_crew)\n        crew_rows = self._siege_emplacement_crew_rows([str(x) for x in defender_refs])\n        bed_requested_crew = bed * bed_optimal_crew\n        bed_fit_crew, bed_crew_control = self._siege_allocate_crew(crew_rows, bed_requested_crew)\n        if bed_fit_crew < bed * bed_min_crew:\n            bed = bed_fit_crew // bed_min_crew\n            bed_requested_crew = bed * bed_optimal_crew\n            bed_fit_crew, bed_crew_control = self._siege_allocate_crew(crew_rows, bed_requested_crew)\n        personnel_left = max(0, personnel - bed_fit_crew)\n        # Trebuchets still prefer real engineering/sapper competence; bed-crossbow\n        # service does not consume a separate crossbow-profession headcount.\n        engineers_left_for_other = min(engineers, personnel_left)\n        treb = min(int(math.floor(treb_inst * condition)), engineers_left_for_other // 60)\n        engineer_left = max(0, engineers_left_for_other - treb * 60)\n        drop = min(int(math.floor(drop_inst * condition)), engineer_left // 4)\n        fire = min(int(math.floor(fire_inst * condition)), max(0, personnel_left - treb * 60 - drop * 4) // 3)\n'''
if old not in s: raise SystemExit('fortress crew allocation block not found')
s=s.replace(old,new2,1)
s=s.replace('''        crew_control = self._siege_crossbow_crew_control([str(x) for x in defender_refs])\n        bed_physics = self._siege_bed_crossbow_physics(\n            range_m=representative_range, condition_pct=condition_pct, fit_crew=bed_fit_crew, active_weapons=bed, crew_control=crew_control\n''','''        crew_control = bed_crew_control\n        bed_physics = self._siege_bed_crossbow_physics(\n            range_m=representative_range, condition_pct=condition_pct, fit_crew=bed_fit_crew, active_weapons=bed, crew_control=crew_control\n''',1)
# Add physical fixture resolver and use it for stock targets.
needle='''    def _ensure_hot_fortified_site_resources(self, site_ref: str, *, at: str, authority_ref: str | None = None) -> dict[str, Any]:\n'''
helper='''    def _fortified_site_installed_bed_crossbows(self, site_ref: str, blueprint: Mapping[str, Any]) -> int:\n        """Resolve physical bed-crossbow fixtures for stock targets without troop-role inference."""\n        _art_ref, art_path = self._site_artillery_identity(str(site_ref))\n        art = self.read_optional(art_path)\n        if isinstance(art, Mapping):\n            installed = art.get("installed") if isinstance(art.get("installed"), Mapping) else art.get("installed_systems", {})\n            if isinstance(installed, Mapping) and "bed_crossbows" in installed:\n                return max(0, int(installed.get("bed_crossbows", 0) or 0))\n        fixtures = blueprint.get("installed_equipment", {}) if isinstance(blueprint.get("installed_equipment"), Mapping) else {}\n        if "bed_crossbows" in fixtures:\n            return max(0, int(fixtures.get("bed_crossbows", 0) or 0))\n        parent = self.read_optional("state/art/tang-manor-artillery.json")\n        if isinstance(parent, Mapping):\n            deriv = parent.get("derivation", {}) if isinstance(parent.get("derivation"), Mapping) else {}\n            if site_ref == "loc_tang_inner_walls":\n                return max(0, int(deriv.get("inner_walls_bed_crossbows", deriv.get("sword_manor_bed_crossbows", 0)) or 0))\n            if site_ref == "loc_tang_inner_citadel":\n                return max(0, int(deriv.get("inner_citadel_bed_crossbows", 0) or 0))\n            if site_ref == "loc_tang_manor":\n                installed = parent.get("installed_systems", {}) if isinstance(parent.get("installed_systems"), Mapping) else {}\n                return max(0, int(installed.get("bed_crossbows", 0) or 0))\n        return 0\n\n'''
if '_fortified_site_installed_bed_crossbows' not in s:
 if needle not in s: raise SystemExit('hot fort helper anchor missing')
 s=s.replace(needle,helper+needle,1)
oldcall='''        targets = current_garrison_requirements(\n            personnel=summary["personnel"], mounts=summary["mounts"], bow_personnel=summary["bow_personnel"], crossbow_personnel=summary["crossbow_personnel"], blueprint=blueprint,\n        )\n'''
newcall='''        bed_crossbows = self._fortified_site_installed_bed_crossbows(site_ref, blueprint)\n        targets = current_garrison_requirements(\n            personnel=summary["personnel"], mounts=summary["mounts"], bow_personnel=summary["bow_personnel"],\n            bed_crossbows=bed_crossbows, blueprint=blueprint,\n        )\n'''
if oldcall not in s: raise SystemExit('garrison requirements call not found')
s=s.replace(oldcall,newcall,1)
p.write_text(s)

p=ROOT/'runtime/sword_runtime/fortified_site_logistics.py'; s=p.read_text()
s=s.replace('''    bow_personnel: int,\n    crossbow_personnel: int,\n    blueprint: Mapping[str, Any],\n''','''    bow_personnel: int,\n    bed_crossbows: int,\n    blueprint: Mapping[str, Any],\n''')
s=s.replace('''        "war_bolts": int(max(0, crossbow_personnel) * 300),''','''        # War bolts belong to installed bed-crossbow magazines, not to a\n        # handheld-crossbow troop headcount.\n        "war_bolts": int(max(0, bed_crossbows) * 300),''')
p.write_text(s)
print('fixed bed-crossbow personnel abstraction')
